// Adaptive Sorting Algorithm Implementation
// This program implements a sorting algorithm that can be evolved to adapt to different data patterns

use std::cmp::Ordering;

// EVOLVE-BLOCK-START
// HYPOTHESIS-1: Hybrid introsort with median-of-three pivot and insertion sort for small subarrays will improve performance and adaptability by avoiding worst-case quicksort behavior
// MECHANISM-1: Median-of-three prevents O(n²) on sorted data; insertion sort is faster for small n; depth limit falls back to heapsort
// EXPECT-1: score > 0.99
// RESULT-1: CONFIRMED (actual=0.9990416691432956)

pub fn adaptive_sort<T: Ord + Clone>(arr: &mut [T]) {
    let len = arr.len();
    if len <= 1 { return; }
    let max_depth = (2.0 * (len as f64).log2()) as usize;
    introsort(arr, max_depth);
}

fn introsort<T: Ord + Clone>(arr: &mut [T], depth: usize) {
    let len = arr.len();
    if len <= 16 {
        insertion_sort(arr);
        return;
    }
    if depth == 0 {
        heapsort(arr);
        return;
    }
    let mid = median_of_three(arr, 0, len / 2, len - 1);
    arr.swap(mid, len - 1);
    let pivot = arr[len - 1].clone();
    let mut i = 0;
    for j in 0..len - 1 {
        if arr[j] <= pivot {
            arr.swap(i, j);
            i += 1;
        }
    }
    arr.swap(i, len - 1);
    let (left, right) = arr.split_at_mut(i);
    introsort(left, depth - 1);
    if right.len() > 1 {
        introsort(&mut right[1..], depth - 1);
    }
}

fn median_of_three<T: Ord>(arr: &[T], a: usize, b: usize, c: usize) -> usize {
    if arr[a] <= arr[b] {
        if arr[b] <= arr[c] { b } else if arr[a] <= arr[c] { c } else { a }
    } else {
        if arr[a] <= arr[c] { a } else if arr[b] <= arr[c] { c } else { b }
    }
}

fn heapsort<T: Ord>(arr: &mut [T]) {
    let n = arr.len();
    for i in (0..n / 2).rev() { sift_down(arr, i, n); }
    for i in (1..n).rev() {
        arr.swap(0, i);
        sift_down(arr, 0, i);
    }
}

fn sift_down<T: Ord>(arr: &mut [T], mut root: usize, end: usize) {
    loop {
        let mut child = 2 * root + 1;
        if child >= end { break; }
        if child + 1 < end && arr[child] < arr[child + 1] { child += 1; }
        if arr[root] >= arr[child] { break; }
        arr.swap(root, child);
        root = child;
    }
}

fn insertion_sort<T: Ord>(arr: &mut [T]) {
    for i in 1..arr.len() {
        let mut j = i;
        while j > 0 && arr[j - 1] > arr[j] {
            arr.swap(j, j - 1);
            j -= 1;
        }
    }
}
// EVOLVE-BLOCK-END

// Benchmark function to test the sort implementation
pub fn run_benchmark(test_data: Vec<Vec<i32>>) -> BenchmarkResults {
    let mut results = BenchmarkResults {
        times: Vec::new(),
        correctness: Vec::new(),
        adaptability_score: 0.0,
    };

    for data in test_data {
        let mut arr = data.clone();
        let start = std::time::Instant::now();

        adaptive_sort(&mut arr);

        let elapsed = start.elapsed();
        results.times.push(elapsed.as_secs_f64());

        // Check if correctly sorted
        let is_sorted = arr.windows(2).all(|w| w[0] <= w[1]);
        results.correctness.push(is_sorted);
    }

    // Calculate adaptability score based on performance variance
    if results.times.len() > 1 {
        let mean_time: f64 = results.times.iter().sum::<f64>() / results.times.len() as f64;
        let variance: f64 = results.times.iter()
            .map(|t| (t - mean_time).powi(2))
            .sum::<f64>() / results.times.len() as f64;

        // Lower variance means better adaptability
        results.adaptability_score = 1.0 / (1.0 + variance.sqrt());
    }

    results
}

#[derive(Debug)]
pub struct BenchmarkResults {
    pub times: Vec<f64>,
    pub correctness: Vec<bool>,
    pub adaptability_score: f64,
}

